SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."body" AS "text", "_root.or.article"."article" AS "article"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("public"."comment"."body") = (('it''s "quoted"')::text))   ORDER BY "id" ASC NULLS LAST LIMIT 3 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.article.base"."title" AS "headline", "_root.or.article.or.author"."author" AS "author"       ) AS "_e"      ) ) AS "article" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."article_id") = ("id"))    LIMIT 1 ) AS "_root.or.article.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.article.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.or.article.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.article.or.author.base"      ) AS "_root.or.article.or.author" ON ('true')      ) AS "_root.or.article" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
